def link(key):
 name,url=sources[key];return f'<a href="{url}">{escape(name)} ↗</a>'
def table(headers,rows):
 return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(str(c))+'</td>' for c in row[:-1])+'<td>'+link(row[-1])+'</td></tr>' for row in rows)+'</tbody></table></div>'
def page(title,body):
 nav=[('Overview','index.html'),('Market & locality','economics.html'),('Projection','projection.html'),('Risks & decisions','risks-decision.html'),('Flagged for review','flagged.html')]
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escape(title)+' | Decision workbook</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="site"><div class="wrap bar"><a class="brand" href="index.html"><span class="dot"></span>Decision workbook</a><nav class="main" aria-label="Main navigation">'+''.join('<a href="'+u+'">'+t+'</a>' for t,u in nav)+'</nav></div></header><main class="wrap"><p><a href="../index.html">← Original workbook</a> · <a href="../session-5bb36a1b/index.html">Prior research dashboard</a></p><h1>'+escape(title)+'</h1>'+body+'<footer><p>Anonymous subject property · Research snapshot 7 November 2026 · Not appraisal, legal or tax advice.</p></footer></main></body></html>'
market=[('City population','3,869,089','July 1, 2025 estimate; citywide, not the trade area.','census'),('Metro employment','6,282,100; +0.5% year over year','September 2026; BLS November summary; not seasonally adjusted. Metropolitan geography differs from city and county.','bls'),('County unemployment','4.5%','September 2026, not seasonally adjusted; may be revised.','fred'),('10-year Treasury yield','4.84%','November 5, 2026; financing benchmark, not a property cap rate.','treasury'),('Jack in the Box system','2,136 restaurants; 93% franchised','FY2025 company disclosure; not proof of this operator’s credit.','sec'),('Fast-food minimum wage','$20 per hour','California FAQ: effective April 1, 2024 for covered workers; applicable status and later changes require checking.','dir'),('Population forecast','','County projection available; model vintage and geography matter. Not a site-level forecast.','dof'),('City median household income','$81,939','2020–2024 in 2024 dollars; citywide, not the local catchment.','census'),('Local income and poverty','','Exact trade area unknown; city/county figures cannot substitute for local catchment.','census'),('Schools','','Site and school catchment unknown; school quality is not verified for this location.','schools'),('Flood exposure','','Location-specific flood zone is unknown.','fema'),('Earthquake / fire exposure','','Location-specific hazards and insurance terms are unknown.','usgs')]
flags=[('Exact location and parcel','','Unknown; no local trade area, flood, fire, zoning or school assertion is justified.','zoning'),('Lease expiration and options','','User reports a 2030–2035 window; lease and option deadlines are unverified.','sec'),('Rent, NOI, rent steps and repairs','','Cannot calculate an asset value or net proceeds without lease and expense records.','sec'),('Tenant and guarantor credit','','System-wide data do not establish the actual obligor or guarantee.','sec'),('Basis, debt, taxes and investor objectives','','After-tax wealth comparison and suitability cannot be established.','irs'),('Insurance, site hazards and environmental condition','','Maps and insurance policy / environmental due diligence are necessary.','fema'),('Prior recommendation thresholds','','The 6% / 7% cutoffs in the Session F summary are analyst assumptions, not verified market evidence or an actionable mandate.','treasury'),('Prior unemployment interpretation','','Session F compares unadjusted June and August rates as an improving labor market; seasonal effects can contribute, and September 2026 was subsequently released.','fred'),('Prior forecasts and repository audit','','Earlier reports contain model assumptions and separate research. Automated link/row checks do not establish factual correctness; the entire repository has not been independently line-by-line reverified in this session.','census')]
risks=[('Sell before expiry','Reduces exposure to expiry and concentration; sacrifices future rent and may crystallize tax, transaction costs and reinvestment risk.','irs'),('Renew then hold','A binding, creditworthy extension could reduce vacancy risk, but rent, guarantee, capital obligations and insurance costs matter. No renewal is assured.','sec'),('Renew then sell','May improve marketability, but negotiation, tenant performance, rates and execution costs remain uncertain.','sec'),('Hold through expiry / re-let','Vacancy, downtime, tenant improvements, permitting and redevelopment risk; assess alternate uses before relying on them.','zoning'),('Disaster / black swan','Earthquake, wildfire, flood and business interruption can damage cash flows; investigate parcel hazards, coverage, deductibles and exclusions.','fema'),('Business as usual','Tenant credit, wage pressure, inflation, financing, taxes and major repairs can reduce cash flow; test lease allocation.','dir'),('Environmental / accessibility','Assess prior uses, site conditions and compliance; NNN language alone does not eliminate owner exposure.','epa')]
body='<div class="callout warn"><strong>Decision is conditional, not a property-specific valuation.</strong> The lease, actual NOI, tenant guarantee, tax basis and parcel location have not been verified. Do not use invented cap-rate cutoffs as a sell signal.</div><h2>Executive summary</h2><p>Start a dual track: privately review lease and tenant credit while seeking a credible renewal and independent sale offers before expiry. Compare after-tax, risk-adjusted proceeds with a documented renewal and realistic hold scenario. If renewal terms and credit are attractive, consider holding or selling with the extension; if not, compare a pre-expiry sale with re-letting or redevelopment. No option can be declared best for this individual on the available facts.</p><p>City and metropolitan indicators provide context, not a site appraisal. See the <a href="economics.html">market table</a>, <a href="projection.html">transparent sensitivity</a>, and <a href="flagged.html">missing facts and verification limits</a>.</p><h2>Research already published</h2><ul><li><a href="../index.html">Root dashboard and category pages</a></li><li><a href="../session-5bb36a1b/index.html">Session F: fresh data and risk analysis</a></li><li><a href="../archive.html">Prior dashboards and research archive</a></li></ul><p>Keep documents and identifiable property details off the public website; use confidential professional channels for review.</p>'
(p/'index.html').write_text(page('A decision, not a prediction',body))
(p/'economics.html').write_text(page('Market & locality','<p>Official data are regional context, not proof of property performance. Blank entries are unverified; different geographies and observation dates must not be mixed as if they described the same place.</p>'+table(['Factor','Published value','Scope / caution','Official source'],market)))
(p/'flagged.html').write_text(page('Flagged for review','<p>Blank values are intentional. Official links are starting points for investigation, not evidence of private property facts.</p>'+table(['Missing or irregular item','Verified value','Why flagged','Official starting point'],flags)))
(p/'risks-decision.html').write_text(page('Risks & decisions','<p>Options depend on verifiable lease rights, executable offers and the owner’s private circumstances. Seek qualified local appraisal, legal, tax, environmental and insurance advice.</p>'+table(['Option / risk','Trade-off and diligence','Official source'],risks)))
scenarios=[('Lower illustrative cap','100,000','5.50%','1,818,182','treasury'),('Middle illustrative cap','100,000','6.25%','1,600,000','treasury'),('Higher illustrative cap','100,000','7.25%','1,379,310','treasury')]
(p/'projection.html').write_text(page('Projection & sensitivity','<p><strong>Illustration only—not a market forecast or appraisal.</strong> Capitalized value = assumed annual stabilized NOI ÷ assumed cap rate. Every number in this table is hypothetical; the Treasury link is context only and does not verify these cap rates. Results exclude debt, sale costs, taxes, vacancy, repairs and renewal expenses.</p>'+table(['Scenario','Assumed NOI ($)','Assumed cap','Calculated value ($)','Benchmark context'],scenarios)+'<h2>How to use the model responsibly</h2><p>Privately verify annual cash flows, rent steps and expenses; model each decision year by year, including vacancies, capex, insurance, debt and taxes. Stress a range of resale prices and discount rates and compare after-tax proceeds over the same horizon. A normalized sensitivity is not a probability or reliable forecast; unsupported probabilities and parcel-specific values remain blank.</p>'))
